function ceiInstructureIconKebab(name) {
  return String(name || '')
    .replace(/([A-Z]+)([A-Z][a-z])/g, '$1-$2')
    .replace(/([a-z])([0-9])/g, '$1-$2')
    .replace(/([0-9])([A-Z])/g, '$1-$2')
    .replace(/([a-z0-9])([A-Z])/g, '$1-$2')
    .toLowerCase();
}

function ceiInstructureIconLabel(name) {
  return ceiInstructureIconKebab(name)
    .split('-')
    .map((part) => {
      if (part === 'ai') return 'AI';
      if (part === 'a11y') return 'A11y';
      if (part === 'lti') return 'LTI';
      if (part === 'sis') return 'SIS';
      if (part === 'rss') return 'RSS';
      if (part === 'pdf') return 'PDF';
      if (part === 'ms') return 'MS';
      return part.charAt(0).toUpperCase() + part.slice(1);
    })
    .join(' ');
}

window.CEI_SVG_ICON_LIBRARY.push(...CEI_INSTRUCTURE_ICON_NAMES.map((name) => {
  const kebab = ceiInstructureIconKebab(name);
  return {
    key: `instructure-${kebab}`,
    label: ceiInstructureIconLabel(name),
    collection: 'instructure',
    category: 'Instructure',
    type: 'instructure',
    iconClass: `icon-${kebab}`
  };
}));
